import{_ as t,c as a,o as n,ag as o}from"./chunks/framework.CQuhCYrb.js";const d=JSON.parse('{"title":"AI-ML Community Content","description":"","frontmatter":{"title":"AI-ML Community Content"},"headers":[],"relativePath":"ai-ml/ai-ml-community-content.md","filePath":"ai-ml/ai-ml-community-content.md","lastUpdated":null}'),i={name:"ai-ml/ai-ml-community-content.md"};function r(s,e,l,m,c,u){return n(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="ai-ml-community-content" tabindex="-1">AI-ML Community Content <a class="header-anchor" href="#ai-ml-community-content" aria-label="Permalink to &quot;AI-ML Community Content&quot;">​</a></h1><h2 id="ai-ml-community-content-1" tabindex="-1">AI-ML Community Content <a class="header-anchor" href="#ai-ml-community-content-1" aria-label="Permalink to &quot;AI-ML Community Content&quot;">​</a></h2><ul><li><p><a href="/general/large-language-models.html">about LLM for the newb</a></p></li><li><p>Platforms and Services</p></li></ul><ul><li>StoryForge (Message Carrick in the AI/ML Chat)</li></ul><ul><li><a href="https://github.com/orgs/irregularchat/discussions?discussions_q=is%3Aopen+label%3A%22AI%2FML+Chat%22+" target="_blank" rel="noreferrer">Community Q&amp;A on GitHub</a> - Engage with the AI/ML community for questions and discussions.</li></ul><h3 id="community-messages" tabindex="-1">Community Messages <a class="header-anchor" href="#community-messages" aria-label="Permalink to &quot;Community Messages&quot;">​</a></h3><h3 id="from-the-air-force" tabindex="-1">From the Air Force <a class="header-anchor" href="#from-the-air-force" aria-label="Permalink to &quot;From the Air Force&quot;">​</a></h3><p>Want to use ChatGPT, but the questions/answers are CUI, FOUO, Sensitive, or otherwise not data you want to share with OpenAI/the Cloud?</p><p>AFRL/RI has setup a Large Language Model (LLM) on Air Force computers which is authorized for use and available for anyone with a CaC card. You can register with your CaC here: https <a href="http://niprgpt.devilops.dso.mil/" target="_blank" rel="noreferrer">http://niprgpt.devilops.dso.mil/</a> AFRL is contemplating SECRET and SCI versions, if there is sufficient interest. Please repost/forward this for maximum exposure.</p><hr><ul><li><p><strong>T.S. Allen:</strong> *(signal)&#39;&#39; DSD Hicks made remarks last week on AI and software in DoD that addressed COTS, DevSecOps, and software usability:</p></li><li><p>“[over the last dozen years or so, advances in machine learning have brought new generations of AI innovation. Much of it, happening outside of government. So our task in the Defense Department today is to adopt those innovations wherever they can add the most military value… AI-enabled systems can greatly improve the speed, quality, and accuracy of commanders’ decisions — which can be decisive in deterring a fight, and winning a fight…</p></li></ul><p>[I]ncreasingly, we&#39;re making the necessary investments to enable and scale data and AI across DoD — with cloud computing contracts, network infrastructure, data integration, faster ways to buy commercial software and keep it up-to-date, and more…..</p><ul><li><p>She calls for DoD to adopt a “DevSecOps mindset.”</p></li><li><p>“Having tools and IT you can use to do your work without tearing your hair out really matters.”</p></li></ul><p>Full remarks: <a href="https://www.defense.gov/News/Speeches/Speech/Article/3683202/remarks-by-deputy-secretary-of-defense-kathleen-hicks-keynote-on-the-global-ai/" target="_blank" rel="noreferrer">https://www.defense.gov/News/Speeches/Speech/Article/3683202/remarks-by-deputy-secretary-of-defense-kathleen-hicks-keynote-on-the-global-ai/</a></p><ul><li><p><strong>M Harp:</strong> *(signal)&#39;&#39; Found an interesting project being worked by our air force peeps. It’s a software solution for ATAK’s that beats GPS Jamming and spoofing even from CUAS platforms. Attached is the executive summary.</p></li><li><p><strong>M Harp:</strong> <em>(signal)</em> <em>[zyn89aznme_4gftt8ohp.pdf]</em></p></li></ul>',15)])])}const p=t(i,[["render",r]]);export{d as __pageData,p as default};
